test_input = G['Test input']
h, w = len(test_input), len(test_input[0])

def apply_rule(grid):
    result = [row[:] for row in grid]

    pattern_row_idx = None
    for i, row in enumerate(grid):
        if any(v > 1 for v in row):
            pattern_row_idx = i
            break

    if pattern_row_idx is None:
        return grid

    pattern_row = grid[pattern_row_idx]

    for col in range(w):
        val = pattern_row[col]

        if val <= 1:
            continue

        # Count consecutive 1s immediately before this column
        count_before = 0
        for c in range(col - 1, -1, -1):
            if pattern_row[c] == 1:
                count_before += 1
            else:
                break

        height = max(1, 7 - count_before)
        top_row = max(0, pattern_row_idx - height + 1)

        # Fill the column with the pattern
        for r in range(top_row, pattern_row_idx + 1):
            if r == top_row or r == pattern_row_idx:
                result[r][col] = val
            else:
                result[r][col] = 1

    return result

output = apply_rule(test_input)
import json
print(json.dumps(output, indent=2))

